-- lovable-cron-fallback-reviewed: User explicitly requires a persisted cancellation every 15 minutes (96 runs/day); a SQL-only schedule needs no HTTP polling or secrets.
create extension if not exists pg_cron;
select cron.schedule('boxflow-cancel-underfilled','*/15 * * * *',$$select public.cancel_underfilled_classes();$$);
alter table public.activity_types add column if not exists logo_url text check (logo_url is null or logo_url ~ '^https://[^[:space:]]+$');
create policy "gym logo read" on storage.objects for select to authenticated using (bucket_id='gym-logos' and (case when (storage.foldername(name))[1]='draft' then (storage.foldername(name))[2]=auth.uid()::text when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then public.is_tenant_member(auth.uid(),((storage.foldername(name))[1])::uuid) else false end));
create policy "gym logo upload" on storage.objects for insert to authenticated with check (bucket_id='gym-logos' and (case when (storage.foldername(name))[1]='draft' then (storage.foldername(name))[2]=auth.uid()::text when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then public.has_tenant_role(auth.uid(),((storage.foldername(name))[1])::uuid,array['admin']::public.tenant_role[]) else false end));
create policy "gym logo delete" on storage.objects for delete to authenticated using (bucket_id='gym-logos' and (case when (storage.foldername(name))[1]='draft' then (storage.foldername(name))[2]=auth.uid()::text when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then public.has_tenant_role(auth.uid(),((storage.foldername(name))[1])::uuid,array['admin']::public.tenant_role[]) else false end));